def add_deadlift(apps, schema_editor):
    """W bazie ćwiczeń brakowało klasycznego martwego ciągu z podłogi."""
    Exercise = apps.get_model('training', 'Exercise')
    BodyArea = apps.get_model('training', 'BodyArea')
    rdl = Exercise.objects.filter(name__endswith=' / Romanian deadlift').first()
    ex, created = Exercise.objects.get_or_create(
        name='Martwy ciąg klasyczny / Deadlift',
        defaults={'muscle_group': rdl.muscle_group if rdl else 'Plecy', 'equipment': 'barbell',
                  'secondary_muscles': 'Plecy, pośladki, czworogłowe uda, przedramiona',
                  'description': 'Podniesienie sztangi z podłogi do pełnego wyprostu bioder i kolan.'})
    if created:
        ex.stressed_areas.set(BodyArea.objects.filter(code__in=['kregoslup-ledzwiowy', 'biodro', 'kolano']))


